import XCTest
@testable import Woontech

final class SajuLessonTests: XCTestCase {

    private let provider = MockSajuLessonProvider()
    private var defaultLesson: Lesson { provider.lesson(id: "L-OH-003") }

    // MARK: - TL07-01 ~ TL07-07: MockSajuLessonProvider 기본값

    func test_mockProvider_defaultLesson_id() {
        XCTAssertEqual(defaultLesson.id, "L-OH-003")
    }

    func test_mockProvider_defaultLesson_numberAndTitle() {
        XCTAssertEqual(defaultLesson.number, 3)
        XCTAssertEqual(defaultLesson.title, "오행의 의미")
    }

    func test_mockProvider_defaultLesson_currentIndex_totalCount() {
        XCTAssertEqual(defaultLesson.currentIndex, 3)
        XCTAssertEqual(defaultLesson.totalCount, 7)
    }

    func test_mockProvider_defaultLesson_sectionLabel_headline() {
        XCTAssertEqual(defaultLesson.sectionLabel, "기본 개념")
        XCTAssertEqual(defaultLesson.headline, "오행이란?")
    }

    func test_mockProvider_defaultLesson_quizChoicesCount_is4() {
        XCTAssertEqual(defaultLesson.quiz.choices.count, 4)
    }

    func test_mockProvider_defaultLesson_correctIndex_is2() {
        XCTAssertEqual(defaultLesson.quiz.correctIndex, 2)
    }

    func test_mockProvider_defaultLesson_nextLessonId_notNil() {
        XCTAssertEqual(defaultLesson.nextLessonId, "L-OH-004")
    }

    // MARK: - TL07-08 ~ TL07-10: progressRatio

    func test_progressRatio_3of7_approx42857() {
        let ratio = SajuLessonView.progressRatio(currentIndex: 3, totalCount: 7)
        XCTAssertEqual(ratio, 3.0 / 7.0, accuracy: 0.00001)
    }

    func test_progressRatio_clamp_above1() {
        let ratio = SajuLessonView.progressRatio(currentIndex: 8, totalCount: 7)
        XCTAssertEqual(ratio, 1.0)
    }

    func test_progressRatio_totalZero_returns0() {
        let ratio = SajuLessonView.progressRatio(currentIndex: 0, totalCount: 0)
        XCTAssertEqual(ratio, 0.0)
    }

    // MARK: - TL07-11 ~ TL07-16: choiceAppearance

    func test_choiceAppearance_beforeSelection_allGray() {
        for index in 0...3 {
            let (border, bg, weight) = SajuLessonView.choiceAppearance(index: index, selected: nil, correct: 2)
            XCTAssertEqual(border, DesignTokens.gray2, "index \(index): border should be gray2")
            XCTAssertEqual(bg, Color.white, "index \(index): bg should be white")
            XCTAssertEqual(weight, Font.Weight.regular, "index \(index): weight should be regular")
        }
    }

    func test_choiceAppearance_correctSelected_inkBorder() {
        let (border, bg, weight) = SajuLessonView.choiceAppearance(index: 2, selected: 2, correct: 2)
        XCTAssertEqual(border, DesignTokens.quizCorrectBorder)
        XCTAssertEqual(bg, DesignTokens.quizCorrectBackground)
        XCTAssertEqual(weight, Font.Weight.bold)
    }

    func test_choiceAppearance_correctSelected_otherStayGray() {
        for index in [0, 1, 3] {
            let (border, _, _) = SajuLessonView.choiceAppearance(index: index, selected: 2, correct: 2)
            XCTAssertEqual(border, DesignTokens.gray2, "index \(index) should stay gray when correct=2 selected=2")
        }
    }

    func test_choiceAppearance_incorrectSelected_redBorder() {
        let (border, bg, _) = SajuLessonView.choiceAppearance(index: 0, selected: 0, correct: 2)
        XCTAssertEqual(border, DesignTokens.quizIncorrectBorder)
        XCTAssertEqual(bg, DesignTokens.quizIncorrectBg)
    }

    func test_choiceAppearance_incorrectSelected_correctHighlighted() {
        let (border, bg, weight) = SajuLessonView.choiceAppearance(index: 2, selected: 0, correct: 2)
        XCTAssertEqual(border, DesignTokens.quizCorrectBorder)
        XCTAssertEqual(bg, DesignTokens.quizCorrectBackground)
        XCTAssertEqual(weight, Font.Weight.bold)
    }

    func test_choiceAppearance_incorrectSelected_otherGray() {
        let (border, _, _) = SajuLessonView.choiceAppearance(index: 1, selected: 0, correct: 2)
        XCTAssertEqual(border, DesignTokens.gray2)
    }

    // MARK: - TL07-17 ~ TL07-20: CTA label / active logic

    func test_ctaLabel_nextLessonIdNotNil_isDaeum() {
        let lesson = defaultLesson // nextLessonId == "L-OH-004"
        XCTAssertNotNil(lesson.nextLessonId)
        let label = lesson.nextLessonId != nil ? "다음 강의" : "학습 완료"
        XCTAssertEqual(label, "다음 강의")
    }

    func test_ctaLabel_nextLessonIdNil_isHakseup() {
        let lesson = provider.lesson(id: "L-OH-LAST") // nextLessonId == nil
        XCTAssertNil(lesson.nextLessonId)
        let label = lesson.nextLessonId != nil ? "다음 강의" : "학습 완료"
        XCTAssertEqual(label, "학습 완료")
    }

    func test_ctaActive_onlyAfterSelection() {
        // nil → disabled
        var selected: Int? = nil
        XCTAssertFalse(selected != nil, "CTA should be inactive before selection")
        // non-nil → enabled
        selected = 2
        XCTAssertTrue(selected != nil, "CTA should be active after selection")
    }

    func test_noReselect_afterFirstSelection() {
        // Simulate guard selectedChoiceIndex == nil behavior
        var selected: Int? = nil
        func tap(index: Int) {
            guard selected == nil else { return }
            selected = index
        }
        tap(index: 2)
        XCTAssertEqual(selected, 2)
        tap(index: 0)
        XCTAssertEqual(selected, 2, "Re-tap should not change selectedChoiceIndex")
    }

    // MARK: - TL07-21 ~ TL07-22: Fallback

    func test_mockProvider_unknownId_returnsFallback() {
        let fallback = provider.lesson(id: "UNKNOWN-XYZ")
        XCTAssertTrue(fallback.isFallback)
    }

    func test_fallbackLesson_quizChoicesStillCount4() {
        let fallback = provider.lesson(id: "__totally_unknown__")
        XCTAssertEqual(fallback.quiz.choices.count, 4)
    }

    // MARK: - TL07-23: Protocol separation

    func test_lessonProviding_separateFrom_learningPathProviding() {
        XCTAssertFalse(MockSajuLessonProvider() is any SajuLearningPathProviding)
    }

    // MARK: - TL07-24 ~ TL07-25: NavBar format strings

    func test_mockProvider_navbarTitle_format() {
        let lesson = defaultLesson
        let title = "\(lesson.number)강 · \(lesson.title)"
        XCTAssertEqual(title, "3강 · 오행의 의미")
    }

    func test_mockProvider_navbarTrailing_format() {
        let lesson = defaultLesson
        let trailing = "\(lesson.currentIndex)/\(lesson.totalCount)"
        XCTAssertEqual(trailing, "3/7")
    }

    // MARK: - TL07-26 ~ TL07-32: VoiceOver helpers

    func test_voiceOver_navbarTitle_accessibilityLabel() {
        let lesson = defaultLesson
        let label = "\(lesson.number)강, \(lesson.title)"
        XCTAssertEqual(label, "3강, 오행의 의미")
    }

    func test_voiceOver_navbarTrailing_accessibilityLabel() {
        let lesson = defaultLesson
        let label = "현재 \(lesson.currentIndex)강, 총 \(lesson.totalCount)강"
        XCTAssertEqual(label, "현재 3강, 총 7강")
    }

    func test_voiceOver_progressBar_accessibilityLabel() {
        let label = SajuLessonView.progressBarA11yLabel(current: 3, total: 7)
        XCTAssertEqual(label, "진행률 43%")
    }

    func test_voiceOver_diagramPlaceholder_accessibilityLabel() {
        let lesson = defaultLesson
        let label = "다이어그램 자리, \(lesson.diagramPlaceholderLabel)"
        XCTAssertEqual(label, "다이어그램 자리, 상생·상극 다이어그램")
    }

    func test_voiceOver_quizChoice_symbol_isAccessibilityLabel() {
        let lesson = defaultLesson
        XCTAssertEqual(lesson.quiz.choices[2].symbol, "金")
    }

    func test_voiceOver_quizCard_accessibilityLabel() {
        let label = SajuLessonView.quizA11yLabel(question: "水를 생(生)하는 오행은?")
        XCTAssertEqual(label, "퀴즈, 水를 생(生)하는 오행은?")
    }

    func test_voiceOver_choiceAccessibilityValue() {
        // 정답 선택
        XCTAssertEqual(SajuLessonView.choiceA11yValue(index: 2, selected: 2, correct: 2), "정답")
        // 오답 선택한 옵션
        XCTAssertEqual(SajuLessonView.choiceA11yValue(index: 0, selected: 0, correct: 2), "오답")
        // 오답 선택 후 다른 미선택 옵션
        XCTAssertEqual(SajuLessonView.choiceA11yValue(index: 1, selected: 0, correct: 2), "")
        // 미선택 상태
        XCTAssertEqual(SajuLessonView.choiceA11yValue(index: 0, selected: nil, correct: 2), "")
    }
}

import XCTest

/// UI tests for WF4-07 레슨 상세 (학습 경험).
///
/// 공통 설정: `-resetOnboarding -openSajuTab` 실행 후
/// `SajuNavPush_lessonLOH003` 버튼으로 `SajuLessonView` 진입.
final class SajuLessonUITests: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
    }

    // MARK: - Helpers

    private func launchSajuTab(extraArgs: [String] = [], extraEnv: [String: String] = [:]) {
        app.launchArguments = ["-resetOnboarding", "-openSajuTab"] + extraArgs
        for (key, value) in extraEnv {
            app.launchEnvironment[key] = value
        }
        app.launch()
        XCTAssertTrue(
            app.otherElements["SajuTabRoot"].waitForExistence(timeout: 5),
            "SajuTabRoot must exist after launch"
        )
    }

    /// SajuLessonView (기본값 L-OH-003)까지 진입.
    private func launchLesson(extraArgs: [String] = [], extraEnv: [String: String] = [:]) {
        launchSajuTab(extraArgs: extraArgs, extraEnv: extraEnv)
        let btn = app.buttons["SajuNavPush_lessonLOH003"]
        XCTAssertTrue(btn.waitForExistence(timeout: 3), "SajuNavPush_lessonLOH003 must exist")
        btn.tap()
        XCTAssertTrue(
            app.otherElements["SajuLessonView"].waitForExistence(timeout: 5),
            "SajuLessonView must appear"
        )
    }

    // MARK: - TU-LS01: SajuLearnListView에서 진입

    func test_navigate_fromLearnList_pushesLesson() {
        launchSajuTab()
        // Navigate to learn list
        let learnBtn = app.buttons["SajuNavPush_learn"]
        XCTAssertTrue(learnBtn.waitForExistence(timeout: 3))
        learnBtn.tap()
        XCTAssertTrue(app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5))
        // Tap lesson card L3 (id="L3", which is "오행의 의미")
        let lessonCard = app.buttons["SajuLearnLessonCard_L3"]
        XCTAssertTrue(lessonCard.waitForExistence(timeout: 3), "SajuLearnLessonCard_L3 must exist")
        lessonCard.tap()
        XCTAssertTrue(
            app.otherElements["SajuLessonView"].waitForExistence(timeout: 5),
            "SajuLessonView must appear after tapping lesson card"
        )
    }

    // MARK: - TU-LS02: UITest push 버튼으로 진입

    func test_navigate_fromSajuNavPush_pushesLesson() {
        launchLesson()
        XCTAssertTrue(app.otherElements["SajuLessonView"].exists)
    }

    // MARK: - TU-LS03: NavBar 타이틀 형식

    func test_navBar_title_format() {
        launchLesson()
        XCTAssertTrue(
            app.navigationBars["3강 · 오행의 의미"].waitForExistence(timeout: 3),
            "NavBar title '3강 · 오행의 의미' must exist"
        )
    }

    // MARK: - TU-LS04: NavBar 우측 진행 텍스트

    func test_navBar_trailing_progress_text() {
        launchLesson()
        XCTAssertTrue(
            app.staticTexts["3/7"].waitForExistence(timeout: 3),
            "Progress text '3/7' must exist in NavBar"
        )
    }

    // MARK: - TU-LS05: 진행 바 존재

    func test_progressBar_exists() {
        launchLesson()
        XCTAssertTrue(
            app.otherElements["SajuLessonProgressBar"].waitForExistence(timeout: 3),
            "SajuLessonProgressBar must exist"
        )
    }

    // MARK: - TU-LS06: sectionLabel 바인딩

    func test_sectionLabel_binding() {
        launchLesson()
        let label = app.staticTexts["SajuLessonSectionLabel"]
        XCTAssertTrue(label.waitForExistence(timeout: 3))
        XCTAssertEqual(label.label, "기본 개념")
    }

    // MARK: - TU-LS07: headline 바인딩

    func test_headline_binding() {
        launchLesson()
        let headline = app.staticTexts["SajuLessonHeadline"]
        XCTAssertTrue(headline.waitForExistence(timeout: 3))
        XCTAssertEqual(headline.label, "오행이란?")
    }

    // MARK: - TU-LS08: 개념 박스 존재

    func test_conceptBox_exists() {
        launchLesson()
        XCTAssertTrue(
            app.otherElements["SajuLessonConceptBox"].waitForExistence(timeout: 3),
            "SajuLessonConceptBox must exist"
        )
    }

    // MARK: - TU-LS09: 다이어그램 placeholder 존재

    func test_diagramPlaceholder_exists() {
        launchLesson()
        XCTAssertTrue(
            app.otherElements["SajuLessonDiagramPlaceholder"].waitForExistence(timeout: 3),
            "SajuLessonDiagramPlaceholder must exist"
        )
    }

    // MARK: - TU-LS10: 퀴즈 선택지 4개 모두 존재

    func test_quizCard_4choices_exist() {
        launchLesson()
        for i in 0...3 {
            XCTAssertTrue(
                app.buttons["SajuLessonQuizChoice_\(i)"].waitForExistence(timeout: 3),
                "SajuLessonQuizChoice_\(i) must exist"
            )
        }
    }

    // MARK: - TU-LS11: CTA 초기 비활성

    func test_ctaButton_initially_disabled() {
        launchLesson()
        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.waitForExistence(timeout: 3))
        XCTAssertFalse(cta.isEnabled, "SajuLessonNextCTA must be initially disabled")
    }

    // MARK: - TU-LS12: 정답 탭 → CTA 활성화

    func test_correctChoice_tap_activatesCTA() {
        launchLesson()
        let choice = app.buttons["SajuLessonQuizChoice_2"] // correctIndex=2
        XCTAssertTrue(choice.waitForExistence(timeout: 3))
        choice.tap()
        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.waitForExistence(timeout: 3))
        XCTAssertTrue(cta.isEnabled, "SajuLessonNextCTA must be enabled after correct choice tap")
    }

    // MARK: - TU-LS13: 오답 탭 → CTA 활성화

    func test_incorrectChoice_tap_activatesCTA() {
        launchLesson()
        let choice = app.buttons["SajuLessonQuizChoice_0"] // incorrect
        XCTAssertTrue(choice.waitForExistence(timeout: 3))
        choice.tap()
        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.waitForExistence(timeout: 3))
        XCTAssertTrue(cta.isEnabled, "SajuLessonNextCTA must be enabled after incorrect choice tap")
    }

    // MARK: - TU-LS14: 두 번째 탭 무시

    func test_secondTap_ignored() {
        launchLesson()
        let choice2 = app.buttons["SajuLessonQuizChoice_2"]
        XCTAssertTrue(choice2.waitForExistence(timeout: 3))
        choice2.tap()
        // Tap another choice
        let choice1 = app.buttons["SajuLessonQuizChoice_1"]
        XCTAssertTrue(choice1.waitForExistence(timeout: 3))
        choice1.tap()
        // CTA should still be enabled (state not reset)
        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.isEnabled, "CTA should remain enabled after second tap")
    }

    // MARK: - TU-LS15: CTA 탭 → replace top (다음 강의)

    func test_nextCTA_nextId_replacesTop() {
        // Navigate from learn list so we can check back behavior
        launchSajuTab()
        let learnBtn = app.buttons["SajuNavPush_learn"]
        XCTAssertTrue(learnBtn.waitForExistence(timeout: 3))
        learnBtn.tap()
        XCTAssertTrue(app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5))

        // Navigate to lesson L-OH-003
        let lessonBtn = app.buttons["SajuNavPush_lessonLOH003"]
        XCTAssertTrue(lessonBtn.waitForExistence(timeout: 3))
        lessonBtn.tap()
        XCTAssertTrue(app.otherElements["SajuLessonView"].waitForExistence(timeout: 5))

        // Tapcorrect choice
        let choice2 = app.buttons["SajuLessonQuizChoice_2"]
        XCTAssertTrue(choice2.waitForExistence(timeout: 3))
        choice2.tap()

        // Tap CTA → should replace with next lesson (L-OH-004 → fallback "준비중")
        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.waitForExistence(timeout: 3))
        cta.tap()

        // Still on a SajuLessonView (the replaced next lesson)
        XCTAssertTrue(
            app.otherElements["SajuLessonView"].waitForExistence(timeout: 5),
            "Should still show SajuLessonView for next lesson"
        )

        // Back should go to LearnList (not to previous lesson)
        app.navigationBars.buttons.firstMatch.tap()
        XCTAssertTrue(
            app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5),
            "Back from replaced lesson should go to SajuLearnListView"
        )
    }

    // MARK: - TU-LS16: -sajuLessonNoNextId → CTA 라벨 "학습 완료"

    func test_nextCTA_noNextId_label_is학습완료() {
        launchSajuTab(extraArgs: ["-sajuLessonNoNextId"])
        let btn = app.buttons["SajuNavPush_lessonNoNext"]
        XCTAssertTrue(btn.waitForExistence(timeout: 3))
        btn.tap()
        XCTAssertTrue(app.otherElements["SajuLessonView"].waitForExistence(timeout: 5))

        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.waitForExistence(timeout: 3))
        XCTAssertTrue(
            cta.label.contains("학습 완료"),
            "CTA label must be '학습 완료' when nextLessonId=nil, got: \(cta.label)"
        )
    }

    // MARK: - TU-LS17: -sajuLessonNoNextId → CTA 탭 → LearnList 복귀

    func test_nextCTA_noNextId_tap_popsToLearnList() {
        launchSajuTab(extraArgs: ["-sajuLessonNoNextId"])
        // Push learn list first so we have something to pop to
        let learnBtn = app.buttons["SajuNavPush_learn"]
        XCTAssertTrue(learnBtn.waitForExistence(timeout: 3))
        learnBtn.tap()
        XCTAssertTrue(app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5))

        let btn = app.buttons["SajuNavPush_lessonNoNext"]
        XCTAssertTrue(btn.waitForExistence(timeout: 3))
        btn.tap()
        XCTAssertTrue(app.otherElements["SajuLessonView"].waitForExistence(timeout: 5))

        // Tap correct choice (correctIndex=1 for lastLesson)
        let choice1 = app.buttons["SajuLessonQuizChoice_1"]
        XCTAssertTrue(choice1.waitForExistence(timeout: 3))
        choice1.tap()

        let cta = app.buttons["SajuLessonNextCTA"]
        XCTAssertTrue(cta.waitForExistence(timeout: 3))
        cta.tap()

        XCTAssertTrue(
            app.otherElements["SajuLearnListView"].waitForExistence(timeout: 5),
            "Should pop to SajuLearnListView after 학습 완료 tap"
        )
    }

